/// <summary>
/// insert
/// </summary>
public void insert()
{
    LedgerJournalTrans ledgerJournalTrans;
    AVALedgerJournalPeriodicCopyTmp ledgerJournalPeriodicCopyTmp;
    LedgerJournalTransRefRecId oldId = this.LedgerJournalTransRecIdOld;
    LedgerJournalTransRefRecId newId = this.LedgerJournalTransRecIdNew;
    select firstonly * from ledgerJournalTrans where ledgerJournalTrans.RecId == this.LedgerJournalTransRecIdOld;   
    next insert();
    if(ledgerJournalTrans.AVAEndDate != dateNull() && ledgerJournalTrans.AVAEndDate < ledgerJournalTrans.TransDate)
    {
        ttsbegin;
        ledgerJournalPeriodicCopyTmp.clear();
        ledgerJournalPeriodicCopyTmp.LedgerJournalTransRecIdNew = newId;
        ledgerJournalPeriodicCopyTmp.LedgerJournalTransRecIdOld = oldId;

        ledgerJournalPeriodicCopyTmp.insert();
        ttscommit;
        //delete_from ledgerJournalPeriodicCopyTmp where ledgerJournalPeriodicCopyTmp.LedgerJournalTransRecIdNew == this.LedgerJournalTransRecIdNew;
    }     
}
